import math

def calculate_E(a, b, c):
    """Calculates the expression E(a, b, c)."""
    if a * b * c == 0:
        return None

    # Ensure we are calculating positive roots for positive integers a, b, c
    try:
        term1 = math.sqrt(1001 / (a * b * c))
        term2 = math.sqrt(a * b) + math.sqrt(b * c) + math.sqrt(c * a)
        return term1 * term2
    except ValueError:
        # Should not happen with positive a, b, c
        return None

def check_integer(value):
    """Checks if a floating point number is close to an integer."""
    if value is None:
        return False
    return abs(value - round(value)) < 1e-6

def search_extended(N):
    count = 0
    solutions = []

    print(f"Starting extended search for a, b, c <= {N}...")

    for a in range(1, N + 1):
        for b in range(1, N + 1):
            for c in range(1, N + 1):
                E = calculate_E(a, b, c)
                if check_integer(E):
                    count += 1
                    solutions.append((a, b, c, E))

    return count, solutions

# Extended search up to N=200
N_extended = 200
count_ext, solutions_ext = search_extended(N_extended)

print(f"Found {count_ext} solutions for a, b, c <= {N_extended}.")
if solutions_ext:
    print("Sample solutions (a, b, c, E):")
    # Print the first few solutions
    for i in range(min(5, len(solutions_ext))):
        a, b, c, E = solutions_ext[i]
        print(f"({a}, {b}, {c}), E = {E}")
else:
    print("No solutions found in the extended range.")

